public class MatrixOps {

    public static IntMatrix add(IntMatrix a, IntMatrix b) {
        if (a.rows() != b.rows() || a.cols() != b.cols()) {
            throw new IllegalArgumentException("matrices must be the same shape");
        }
        IntMatrix sum = new IntMatrix(a.rows(), a.cols());
        for (int r = 0; r < a.rows(); r++) {
            for (int c = 0; c < a.cols(); c++) {
                sum.set(r, c, a.get(r, c) + b.get(r, c));
            }
        }
        return sum;
    }

    public static IntMatrix transpose(IntMatrix m) {
        IntMatrix result = new IntMatrix(m.cols(), m.rows());
        for (int r = 0; r < m.rows(); r++) {
            for (int c = 0; c < m.cols(); c++) {
                result.set(c, r, m.get(r, c));
            }
        }
        return result;
    }

    public static int[] columnMaxima(IntMatrix m) {
        if (m.rows() == 0) {
            return new int[0];
        }
        int[] maxima = new int[m.cols()];
        for (int c = 0; c < m.cols(); c++) {
            int best = m.get(0, c);
            for (int r = 1; r < m.rows(); r++) {
                best = Math.max(best, m.get(r, c));
            }
            maxima[c] = best;
        }
        return maxima;
    }

    public static boolean isSymmetric(IntMatrix m) {
        if (m.rows() != m.cols()) {
            return false;
        }
        for (int r = 0; r < m.rows(); r++) {
            for (int c = 0; c < m.cols(); c++) {
                if (m.get(r, c) != m.get(c, r)) {
                    return false;
                }
            }
        }
        return true;
    }
}

