public class MatrixOpsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String show(IntMatrix m) {
        return m == null ? "null matrix" : m.toString();
    }

    public static void main(String[] args) {
        IntMatrix a = IntMatrix.of(new int[][]{{1, 2, 3}, {4, 5, 6}});
        check("of copies the values", "1,2,3;4,5,6", show(a));
        check("rows", 2, a.rows());
        check("cols", 3, a.cols());
        check("get a cell", 6, a.get(1, 2));

        IntMatrix blank = new IntMatrix(2, 2);
        blank.set(0, 1, 7);
        check("set then get", 7, blank.get(0, 1));
        check("a fresh matrix is zeroed", "0,7;0,0", show(blank));

        int[] copied = a.row(0);
        if (copied.length > 0) {
            copied[0] = 99;
        }
        check("row hands back a copy", 1, a.get(0, 0));
        check("second row contents", "[4, 5, 6]", java.util.Arrays.toString(a.row(1)));
        check("toArray contents", "[[1, 2, 3], [4, 5, 6]]",
              java.util.Arrays.deepToString(a.toArray()));

        IntMatrix b = IntMatrix.of(new int[][]{{10, 10, 10}, {0, 0, 0}});
        check("add", "11,12,13;4,5,6", show(MatrixOps.add(a, b)));
        String mismatch = "no exception";
        try {
            MatrixOps.add(a, new IntMatrix(3, 3));
            mismatch = "no exception";
        } catch (IllegalArgumentException e) {
            mismatch = "IllegalArgumentException";
        } catch (RuntimeException e) {
            mismatch = e.getClass().getSimpleName();
        }
        check("adding different shapes", "IllegalArgumentException", mismatch);

        check("transpose", "1,4;2,5;3,6", show(MatrixOps.transpose(a)));
        check("column maxima", "[4, 5, 6]",
              java.util.Arrays.toString(MatrixOps.columnMaxima(a)));
        check("column maxima of no rows", "[]",
              java.util.Arrays.toString(MatrixOps.columnMaxima(new IntMatrix(0, 0))));
        check("a symmetric matrix", true,
              MatrixOps.isSymmetric(IntMatrix.of(new int[][]{{1, 2}, {2, 1}})));
        check("an asymmetric square matrix", false,
              MatrixOps.isSymmetric(IntMatrix.of(new int[][]{{1, 2}, {3, 1}})));
        check("a non-square matrix is never symmetric", false, MatrixOps.isSymmetric(a));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

